css:
/* From Uiverse.io by Lucaasbre  - Tags: minimalist, warning, card, modern, clean, confirm, modal, security */
.__UIV_SCOPE__ .confirm-div {
  background-color: #ccc;
}

.__UIV_SCOPE__ .green-btn {
  background-color: #47a04b;
}

.__UIV_SCOPE__ .green-btn:hover {
  background-color: #368339;
}

.__UIV_SCOPE__ .green-btn:active {
  background-color: #2d6830;
}

.__UIV_SCOPE__ .green-btn:disabled {
  background-color: #c8eac9;
  color: #1b7a43;
}

.__UIV_SCOPE__ .red-btn {
  background-color: #f93a3a;
}

.__UIV_SCOPE__ .red-btn:hover {
  background-color: #e71f1f;
}

.__UIV_SCOPE__ .red-btn:active {
  background-color: #c21313;
}

.__UIV_SCOPE__ .red-btn:disabled {
  background-color: #ffc7c7;
  color: #c21313;
}

.__UIV_SCOPE__ .confirm-div {
  font-size: 14px;
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 300px;
  padding: 20px;
  text-align: center;
  border-radius: 6px;
  box-shadow: 4px 4px 15px #3e3e3e;
  font-family: "Segoe UI", Tahoma, sans-serif;
  cursor: default;
}

.__UIV_SCOPE__ .confirm-div button {
  cursor: pointer;
  width: 100%;
  padding: 4px 6px;
  border-radius: 4px;
  color: #fff;
  border: none;
  height: 30px;
  width: 100%;
}

.__UIV_SCOPE__ .confirm-div p {
  display: flex;
  flex-direction: column;
}

.__UIV_SCOPE__ .confirm-div p strong {
  margin-bottom: 15px;
}

.__UIV_SCOPE__ .warning-general {
  position: absolute; /* switch to fixed */
  top: 0;
  left: 0;
  z-index: 999;
  width: 100%;
  height: 100%;
  backdrop-filter: blur(2px);
}

.__UIV_SCOPE__ .modals-container {
  display: flex;
  flex-direction: row;
  height: 32px;
  margin-top: 20px;
  gap: 7px;
  width: 100%;
}
